1	/* RVV inside the ROI. The workload is an 8x8x8 int32 GEMM, but the
2	 * demo tests the vector unit, not the math.
3	 *
4	 * The other demos move DATA across the hybrid handoff; this one moves
5	 * COMPUTE. The ROI runs a vector kernel written with the standard RVV
6	 * intrinsics (<riscv_vector.h>), proving
7	 *   - the toolchain's RVV intrinsics compile and run on every mode,
8	 *   - on hybrid, the vector unit works right after the handoff: the
9	 *     restored mstatus.VS and V CSRs let the ROI issue vector
10	 *     instructions with no V setup code of its own.
11	 *
12	 * The kernel is INTEGER on purpose: this engine's VPU is integer-only
13	 * (config: VECTOR_SINT/VDOT/INT4, no vector FP32) -- a vector-float op
14	 * like vfmacc.vf traps illegal-instruction on the RTL even though
15	 * QEMU's model accepts it. int32 matches the hardware on both engines.
16	 *
17	 * QEMU phase (before the ROI):
18	 *   - fill A and B with runtime-computed small values
19	 *   - compute the scalar reference C_ref
20	 *
21	 * vsim ROI:
22	 *   - C = A x B with vle32/vmacc/vse32, strip-mined by vsetvl so the
23	 *     kernel is correct for any VLEN
24	 *   - compare C with C_ref; prints RVV_OK / RVV_BAD
25	 *
26	 * A, B, C_ref live in normal DRAM -- the shared mmap -- which is how
27	 * they survive the QEMU -> vsim handoff.
28	 */
29	
30	#include <stdint.h>
31	#include <stdio.h>
32	#include <riscv_vector.h>
33	#include <andesim/ROI.h>
34	
35	#define N 8
36	
37	static int32_t A[N][N], B[N][N], C[N][N], C_ref[N][N];
38	
39	/* Small values in [-8, 7]. */
40	static inline int32_t elem(uint32_t i, uint32_t salt)
41	{
42	  uint32_t h = (i + salt) * 2654435761u;
43	  return (int32_t) (h >> 28) - 8;
44	}
45	
46	/* ROI body, noinline and non-static so --trigger pc can name it. */
47	__attribute__((noinline)) int rvv_kernel(void)
48	{
49	  for (int i = 0; i < N; i++) {
50	    int j = 0;
51	    while (j < N) {
52	      size_t vl = __riscv_vsetvl_e32m1((size_t) (N - j));
53	      vint32m1_t acc = __riscv_vmv_v_x_i32m1(0, vl);
54	      for (int k = 0; k < N; k++) {
55	        vint32m1_t b = __riscv_vle32_v_i32m1(&B[k][j], vl);
56	        acc = __riscv_vmacc_vx_i32m1(acc, A[i][k], b, vl);
57	      }
58	      __riscv_vse32_v_i32m1(&C[i][j], acc, vl);
59	      j += (int) vl;
60	    }
61	  }
62	
63	  uint32_t bad = 0;
64	  for (int i = 0; i < N; i++)
65	    for (int j = 0; j < N; j++)
66	      bad += (C[i][j] != C_ref[i][j]);
67	
68	  if (bad != 0) {
69	    printf("RVV_BAD count=%u\n", (unsigned) bad);
70	    return 1;
71	  }
72	  printf("RVV_OK n=%u\n", (unsigned) (N * N));
73	  return 0;
74	}
75	
76	int main(void)
77	{
78	  for (int i = 0; i < N; i++)
79	    for (int k = 0; k < N; k++) {
80	      A[i][k] = elem((uint32_t) (i * N + k), 0xA11Au);
81	      B[i][k] = elem((uint32_t) (i * N + k), 0xB22Bu);
82	    }
83	
84	  for (int i = 0; i < N; i++)
85	    for (int j = 0; j < N; j++) {
86	      int32_t s = 0;
87	      for (int k = 0; k < N; k++) s += A[i][k] * B[k][j];
88	      C_ref[i][j] = s;
89	      C[i][j] = 0;
90	    }
91	  printf("GEMM 8x8x8 staged\n");
92	
93	  andesim_ROI_begin();
94	  int rc = rvv_kernel();
95	  andesim_ROI_end();
96	  /* ROI end symbol for --pc-end: the point right after the call. */
97	  __asm__ __volatile__(".globl rvv_roi_end\nrvv_roi_end:" ::: "memory");
98	
99	  return rc;
100	}
