1	/* ILM/DLM content transport across the hybrid handoff.
2	 *
3	 * QEMU phase (before the ROI):
4	 *   - enable the ILM and DLM (EN bit of milmb 0x7C0 / mdlmb 0x7C1)
5	 *   - fill the whole DLM with a runtime-computed pattern
6	 *   - assemble a 3-instruction kernel a0 = (a0 ^ IMM) + 0x321 into the
7	 *     ILM and call it once as a sanity check
8	 *
9	 * vsim ROI:
10	 *   - call the ILM kernel again (the fetch hits the ILM RTL SRAM)
11	 *   - compare every DLM word against the pattern
12	 *   - print the verdict: LM_OK, or ILM_BAD / DLM_BAD
13	 *
14	 * The pattern and the kernel bytes exist NOWHERE except the local
15	 * memories -- they are computed at runtime, not stored in the ELF, and
16	 * QEMU keeps ILM/DLM in per-CPU overlays outside the shared mmap. The
17	 * only road to vsim is andesim's sidecar transport (<state>.ilm/.dlm,
18	 * backdoor-loaded into the RTL SRAMs). No transport => LM_*_BAD, and an
19	 * empty ILM fetches 0x00000000 = illegal instruction, so failure is loud.
20	 *
21	 * Geometry matches vsim:ax45mpv_premium hart 0 (see the engine's
22	 * --describe): ILM 64 KB at 0x0 (kernel at 0x100, clear of NULL),
23	 * DLM 32 KB at 0x200000. The program image sits at 0x100000, between
24	 * the two windows. andesim syncs this geometry to QEMU automatically
25	 * on the hybrid path.
26	 */
27	
28	#include <stdint.h>
29	#include <stdio.h>
30	#include <andesim/ROI.h>
31	
32	#define ILM_FN_ADDR 0x100u
33	#define DLM_BASE    0x200000u
34	#define DLM_BYTES   32768u
35	#define DLM_WORDS   (DLM_BYTES / 4u)
36	
37	typedef uint32_t (*ilm_fn)(uint32_t);
38	
39	/* Enable a local memory the way firmware does: read-modify-write the EN
40	 * bit, preserving the WARL base/size fields. CSR number must be a
41	 * literal in the asm string, hence the macro. */
42	#define LM_ENABLE(csr_lit)                                        \
43	  do {                                                            \
44	    unsigned long long v_;                                        \
45	    __asm__ __volatile__("csrr %0, " csr_lit : "=r"(v_));         \
46	    __asm__ __volatile__("csrw " csr_lit ", %0" ::"r"(v_ | 1));   \
47	    __asm__ __volatile__("fence" ::: "memory");                   \
48	  } while (0)
49	
50	/* Per-word pattern: cheap, position-dependent, never all-zero. */
51	static inline uint32_t pat(uint32_t i) { return i * 2654435761u + 0x5A17u; }
52	
53	/* Runtime-volatile so neither the expected value nor the patched
54	 * instruction can be folded into a compile-time constant. */
55	static volatile uint32_t imm_src = 0x5A5u;
56	
57	/* The ROI body, noinline and non-static so --trigger pc can name it: the
58	 * pc window is lm_check .. lm_roi_end, the marker window is the HINTs
59	 * around the call. */
60	__attribute__((noinline)) int lm_check(ilm_fn f, uint32_t x, uint32_t want)
61	{
62	  volatile uint32_t *dlm = (volatile uint32_t *) (uintptr_t) DLM_BASE;
63	
64	  uint32_t got = f(x);
65	  if (got != want) {
66	    printf("ILM_BAD got=0x%08x want=0x%08x\n", (unsigned) got,
67	           (unsigned) want);
68	    return 1;
69	  }
70	
71	  uint32_t bad = 0, first = 0;
72	  for (uint32_t i = 0; i < DLM_WORDS; i++) {
73	    if (dlm[i] != pat(i)) {
74	      if (bad == 0) first = i;
75	      bad++;
76	    }
77	  }
78	  if (bad != 0) {
79	    printf("DLM_BAD count=%u first=%u got=0x%08x want=0x%08x\n",
80	           (unsigned) bad, (unsigned) first, (unsigned) dlm[first],
81	           (unsigned) pat(first));
82	    return 1;
83	  }
84	
85	  printf("LM_OK ilm=0x%08x dlm_words=%u\n", (unsigned) got,
86	         (unsigned) DLM_WORDS);
87	  return 0;
88	}
89	
90	int main(void)
91	{
92	  LM_ENABLE("0x7c0"); /* milmb: ILM on */
93	  LM_ENABLE("0x7c1"); /* mdlmb: DLM on */
94	
95	  /* Fill the DLM with the runtime-computed pattern. */
96	  volatile uint32_t *dlm = (volatile uint32_t *) (uintptr_t) DLM_BASE;
97	  for (uint32_t i = 0; i < DLM_WORDS; i++) dlm[i] = pat(i);
98	
99	  /* Assemble the ILM kernel:
100	   *   xori a0, a0, IMM   (I-type, base 0x00054513, IMM patched at runtime)
101	   *   addi a0, a0, 0x321 (0x32150513)
102	   *   ret                (0x00008067)                                    */
103	  const uint32_t imm = imm_src & 0xFFFu;
104	  volatile uint32_t *ilm = (volatile uint32_t *) (uintptr_t) ILM_FN_ADDR;
105	  ilm[0] = 0x00054513u | (imm << 20);
106	  ilm[1] = 0x32150513u;
107	  ilm[2] = 0x00008067u;
108	  __asm__ __volatile__("fence.i" ::: "memory");
109	
110	  ilm_fn f = (ilm_fn) (uintptr_t) ILM_FN_ADDR;
111	  const uint32_t x = 0x1234u;
112	  const uint32_t want = (x ^ imm) + 0x321u;
113	
114	  /* Pre-ROI sanity: a failure here is a setup problem, not transport. */
115	  if (f(x) != want) {
116	    printf("LM_STAGE_BAD\n");
117	    return 2;
118	  }
119	  printf("LM staged\n");
120	
121	  andesim_ROI_begin();
122	  int rc = lm_check(f, x, want);
123	  andesim_ROI_end();
124	  /* ROI end symbol for --pc-end: the point right after the call. */
125	  __asm__ __volatile__(".globl lm_roi_end\nlm_roi_end:" ::: "memory");
126	
127	  return rc;
128	}
