/*
 * CoreMark port for andesim-demo.
 *
 * Timing is based on the RISC-V cycle counter so the benchmark can run inside
 * the simulator without relying on host time APIs.
 *
 * The andesim ROI markers live HERE, in the port layer, not in the EEMBC
 * benchmark sources: start_time() opens the ROI, stop_time() closes it, so
 * the hybrid window is exactly the region CoreMark itself times. The markers
 * are HINT NOPs, so fast and cycle runs are unaffected. On hybrid the run
 * ends at stop_time()'s marker (that is where the cycle figure is drained),
 * so CoreMark's own report after the timed run prints on fast and cycle only.
 */

#include <stdio.h>
#include <stdlib.h>
#include <andesim/ROI.h>

#include "coremark.h"

#if (MEM_METHOD == MEM_MALLOC)
void *
portable_malloc(size_t size)
{
    return malloc(size);
}

void
portable_free(void *p)
{
    free(p);
}
#else
void *
portable_malloc(size_t size)
{
    (void)size;
    return NULL;
}

void
portable_free(void *p)
{
    (void)p;
}
#endif

#if (SEED_METHOD == SEED_VOLATILE)
#if VALIDATION_RUN
volatile ee_s32 seed1_volatile = 0x3415;
volatile ee_s32 seed2_volatile = 0x3415;
volatile ee_s32 seed3_volatile = 0x66;
#endif
#if PERFORMANCE_RUN
volatile ee_s32 seed1_volatile = 0x0;
volatile ee_s32 seed2_volatile = 0x0;
volatile ee_s32 seed3_volatile = 0x66;
#endif
#if PROFILE_RUN
volatile ee_s32 seed1_volatile = 0x8;
volatile ee_s32 seed2_volatile = 0x8;
volatile ee_s32 seed3_volatile = 0x8;
#endif
volatile ee_s32 seed4_volatile = ITERATIONS;
volatile ee_s32 seed5_volatile = 0;
#endif

#define TIMER_RES_DIVIDER 50000
#define EE_TICKS_PER_SEC (1000000000 / TIMER_RES_DIVIDER)

static CORE_TICKS start_time_val;
static CORE_TICKS stop_time_val;

static CORE_TICKS
read_cycle_counter(void)
{
    unsigned long cycle;

    asm volatile("csrr %0, mcycle" : "=r"(cycle));
    return (CORE_TICKS)cycle;
}

/* ROI markers sit OUTSIDE the mcycle reads, so CoreMark's own tick count
 * is a subset of the hybrid window: cycle mode's "Total ticks" and the
 * hybrid "[andesim] N cycles" figure measure the same region. */
void
start_time(void)
{
    andesim_ROI_begin();
    start_time_val = read_cycle_counter();
}

void
stop_time(void)
{
    stop_time_val = read_cycle_counter();
    andesim_ROI_end();
}

CORE_TICKS
get_time(void)
{
    return (CORE_TICKS)(stop_time_val - start_time_val);
}

secs_ret
time_in_secs(CORE_TICKS ticks)
{
    return ((secs_ret)ticks) / (secs_ret)EE_TICKS_PER_SEC;
}

ee_u32 default_num_contexts = 1;

void
portable_init(core_portable *p, int *argc, char *argv[])
{
    (void)argc;
    (void)argv;

    if (sizeof(ee_ptr_int) != sizeof(ee_u8 *))
    {
        ee_printf("ERROR! Please define ee_ptr_int to a type that holds a pointer!\n");
    }
    if (sizeof(ee_u32) != 4)
    {
        ee_printf("ERROR! Please define ee_u32 to a 32b unsigned type!\n");
    }
    p->portable_id = 1;
}

void
portable_fini(core_portable *p)
{
    p->portable_id = 0;
}

/* Why timing-config transport matters: the cache-enable state.
 *
 * The andesim runtime's crt0 enables the L1 I/D caches by writing
 * mcache_ctl (0x7CA) at boot. On hybrid that write runs on QEMU, which
 * models no caches -- the ONLY reason the vsim ROI runs cached is that
 * the handoff transports the written mcache_ctl value and restores it
 * before the ROI resumes. This demo makes that visible as a number:
 *
 *   cache_on.elf   the default program: crt0's enable is transported,
 *                  the ROI runs WITH L1 caches -- what this program
 *                  would do on real silicon.
 *   cache_off.elf  same source, -DCACHE_OFF: the program clears
 *                  mcache_ctl.IC_EN|DC_EN (bits 0|1) before the ROI,
 *                  so the transported value disables the caches and
 *                  the same kernel runs UNCACHED -- every instruction
 *                  fetch and data access goes out to DRAM.
 *
 * The gap between the two figures is what the transport buys; without
 * it, EVERY hybrid window would measure like cache_off (the engine's
 * reset default is caches-disabled). It is also a write-mask demo: a
 * config CSR is restored only because the program (crt0 or the
 * CACHE_OFF line) actually wrote it.
 *
 * The ROI is a pure kernel -- PASSES sweeps over a 4 KB volatile array,
 * no I/O inside the window. The checksum verdict (CACHE_OK) prints
 * after the ROI, so it appears on fast and cycle only; on hybrid the
 * output is just the cycle figure, compared by check.sh.
 *
 * There is deliberately NO cache_off cycle target: from reset on the
 * RTL the program runs cached until the clear, so disabling the
 * D-cache mid-run would strand its dirty lines (that needs a CCTL
 * writeback-invalidate first). On hybrid the vsim caches start empty
 * at the restore, so the plain disable is safe and exact.
 */

#include <stdint.h>
#include <stdio.h>
#include <andesim/ROI.h>

/* Sized for the UNCACHED case: every fetch and load then goes to DRAM,
 * costing tens of cycles each on the RTL, and the whole window must
 * still finish inside the driver's 90 s per-leg budget on a kHz-class
 * RTL simulation. 4 passes x 256 words keeps the uncached window in
 * the low hundreds of thousands of cycles. */
#define PASSES 4
#define WORDS  256  /* 1 KB: fits easily in the L1 D-cache */

/* volatile: every element read is a real load on every pass -- the
 * compiler can neither cache the array in registers nor fold the
 * per-pass sums into one sweep. */
static volatile int32_t buf[WORDS];

/* Small values in [-8, 7]. */
static inline int32_t elem(uint32_t i)
{
  uint32_t h = (i + 0xCACEu) * 2654435761u;
  return (int32_t) (h >> 28) - 8;
}

/* ROI body, noinline and non-static so --trigger pc can name it. */
__attribute__((noinline)) long cache_kernel(void)
{
  long sum = 0;
  for (int p = 0; p < PASSES; p++)
    for (int i = 0; i < WORDS; i++)
      sum += buf[i];
  return sum;
}

int main(void)
{
  long single = 0;
  for (int i = 0; i < WORDS; i++) {
    buf[i] = elem((uint32_t) i);
    single += buf[i];
  }
  long want = (long) PASSES * single;

#ifdef CACHE_OFF
  /* Clear mcache_ctl.IC_EN|DC_EN. The write-mask records this CSR
   * write, so the handoff restores the DISABLED state into vsim. */
  __asm__ __volatile__("csrrc x0, 0x7ca, %0" : : "r"(3UL));
  printf("CACHE staged: %u KB x %u passes, caches DISABLED for the ROI\n",
         (unsigned) (sizeof buf / 1024), (unsigned) PASSES);
#else
  printf("CACHE staged: %u KB x %u passes, crt0 cache enable transported\n",
         (unsigned) (sizeof buf / 1024), (unsigned) PASSES);
#endif

  andesim_ROI_begin();
  long sum = cache_kernel();
  andesim_ROI_end();
  /* ROI end symbol for --pc-end: the point right after the call. */
  __asm__ __volatile__(".globl cache_roi_end\ncache_roi_end:" ::: "memory");

  /* Runs on fast and cycle only: a hybrid run ended at the exit trigger. */
  if (sum != want) {
    printf("CACHE_BAD sum=%ld want=%ld\n", sum, want);
    return 1;
  }
  printf("CACHE_OK sum=%ld\n", sum);
  return 0;
}

/* memsize demo: ONE ELF, run under various --mem-size.
 *
 * The payload verifies a small working set (4 KiB), so it runs unchanged on
 * fast, cycle AND hybrid, at ANY valid --mem-size -- the checksum never depends
 * on how much RAM the driver hands out.
 *
 * FOOTPRINT_MB (default 0) reserves a large static .bss array. The "big" build
 * (-DFOOTPRINT_MB=64) pushes the ELF's static-image top past a small --mem-size,
 * so the driver rejects it BEFORE any guest code runs (a pure driver check, not
 * a runtime fault). That is how --mem-size becomes observable in program terms;
 * see the Makefile `fit` / `check` targets.
 *
 * ROI markers are RISC-V HINT NOPs, so the same binary also runs standalone on
 * silicon; pc-trigger names the same window as `work` .. memsize_roi_end.
 */
#include <stdint.h>
#include <stdio.h>

#include <andesim/ROI.h>

#ifndef FOOTPRINT_MB
#define FOOTPRINT_MB 0
#endif
#if FOOTPRINT_MB > 0
volatile uint8_t footprint[(unsigned)FOOTPRINT_MB * 1024u * 1024u];
#endif

#define NWORDS 1024 /* 4 KiB working set: cheap even in cycle-accurate mode */
static uint32_t buf[NWORDS];

__attribute__((noinline)) uint32_t work(void)
{
  uint32_t sum = 0;
  for (int i = 0; i < NWORDS; i++)
    buf[i] = (uint32_t) i * 2654435761u; /* Knuth multiplicative hash */
  for (int i = 0; i < NWORDS; i++)
    sum += buf[i];
  return sum;
}

int main(void)
{
  andesim_ROI_begin();
  uint32_t sum = work();
  andesim_ROI_end();
  /* ROI end symbol for --pc-end: the point right after the measured window. */
  __asm__ __volatile__(".globl memsize_roi_end\nmemsize_roi_end:" ::: "memory");

#if FOOTPRINT_MB > 0
  footprint[0] = (uint8_t) sum; /* keep the reservation live */
  printf("memsize PASS checksum=0x%08x footprint=%dMB\n", sum, FOOTPRINT_MB);
#else
  printf("memsize PASS checksum=0x%08x\n", sum);
#endif
  return 0;
}

