1	/* vplat: one newlib syscall layer that works on EVERY engine.
2	 *
3	 * Replaces -lgloss_vh (semihosting) so a single ELF runs unmodified on
4	 * QEMU (fast), vsim (cycle) and across a hybrid handoff. It only touches
5	 * channels both engines model at the same addresses:
6	 *
7	 *   stdio (fd 0-2)  ATCUART100 UART2: THR @0xf0300020, LSR @0xf0300034.
8	 *                   QEMU: serial_mm_init(UART2+0x20, shift 2) = serial_hd(0);
9	 *                   vsim: src/platform/uart.hpp (vsim repo) -> host stdout.
10	 *   exit            SimControl @0xe0080000: u32 exit code (<256).
11	 *                   vsim: sim_control.hpp; QEMU: hw/riscv/andes_ae350.c
12	 *                   (sim_ctrl_write).
13	 *   file io (fd>2)  the SimControl syscall WINDOW @0xe0080800: eight u64
14	 *                   arg/result slots + a data area for payloads, doorbell
15	 *                   @0xe0080028. Served host-side (vsim: sim_control.hpp
16	 *                   dispatch_window; QEMU: andes_ae350.c's mirror).
17	 *
18	 * The window lives in DEVICE space (PMA-uncached on every engine), so the
19	 * whole exchange is coherent by construction: no guest cache line can
20	 * shadow a host write. Its predecessor -- a magicmem block in cacheable
21	 * RAM that the host peeked/poked by backdoor -- broke on any core with a
22	 * private write-back L2 (ax66 PL2C): the guest read its own stale copy of
23	 * the host's result, and no guest-side CCTL sequence can fix that (the
24	 * VA-scoped forms trap on RVH cores, the ALL forms drop unrelated dirty
25	 * lines). Marshaling payloads through the window costs a few uncached
26	 * copies per call; correctness on every cache hierarchy is worth it.
27	 *
28	 * No semihosting, no ecall, and no "which engine am I on" probe -- hybrid
29	 * migrates the running process between engines, so any boot-time detection
30	 * would go stale at the handoff. Every call must be engine-blind.
31	 */
32	
33	#include <stdint.h>
34	#include <stddef.h>
35	#include <sys/stat.h>
36	#include <unistd.h>
37	
38	/* ---- UART2 (console) ------------------------------------------------- */
39	
40	#define UART_THR (*(volatile uint32_t*) 0xf0300020UL)
41	#define UART_LSR (*(volatile uint32_t*) 0xf0300034UL)
42	#define UART_LSR_THRE 0x20u
43	
44	static void uart_putc(char c)
45	{
46	  while (!(UART_LSR & UART_LSR_THRE))
47	    ;
48	  UART_THR = (uint32_t) (unsigned char) c;
49	}
50	
51	/* ---- SimControl: exit + syscall window -------------------------------- */
52	
53	#define SIM_EXIT_ADDR   0xe0080000UL
54	#define SYSCALL_GO_ADDR 0xe0080028UL
55	
56	/* Window layout -- must match the hosts (vsim src/platform/sim_control.hpp
57	 * SYSCALL_WINDOW_*; QEMU hw/riscv/andes_ae350.c ANDESIM_SYSCALL_*):
58	 * eight u64 arg/result slots, then the payload data area. All guest
59	 * accesses are u64 loads/stores (the access width every engine already
60	 * proves out on the legacy 0x10 doorbell). */
61	#define WIN_SLOTS ((volatile uint64_t*) 0xe0080800UL)
62	#define WIN_DATA_VA 0xe0080840UL
63	#define WIN_DATA_SIZE (0x800u - 0x40u) /* 1984 bytes, 8-aligned */
64	
65	/* HTIF syscall numbers -- must match the table in the vsim repo's
66	 * src/platform/sim_control.hpp (and the QEMU mirror device). */
67	#define VH_SYS_GETTIMEOFDAY 5
68	#define VH_SYS_OPEN         6
69	#define VH_SYS_WRITE        7
70	#define VH_SYS_GETCWD       8
71	#define VH_SYS_LSEEK        9
72	#define VH_SYS_READ         10
73	#define VH_SYS_FLEN         11
74	#define VH_SYS_CLOSE        12
75	#define VH_SYS_ACCESS       13
76	#define VH_SYS_FACCESSAT    14
77	#define VH_SYS_FSTAT        15
78	#define VH_SYS_FSTATAT      16
79	#define VH_SYS_LINK         17
80	#define VH_SYS_LSTAT        18
81	#define VH_SYS_STAT         19
82	#define VH_SYS_OPENAT       20
83	#define VH_SYS_RENAME       21
84	#define VH_SYS_UNLINK       22
