170	/* ---- newlib stubs ------------------------------------------------------
171	 *
172	 * stat family note: the guest's struct bounces through the window BOTH
173	 * ways, so fields the host does not fill keep the caller's values (the
174	 * hosts write pico_stat's st_mode/st_size at their newlib offsets). */
175	
176	__attribute__((used)) ssize_t _write(int fd, const void* ptr, size_t len)
177	{
178	  if (fd > 2) {
179	    const unsigned char* p = (const unsigned char*) ptr;
180	    size_t done = 0;
181	    while (done < len) {
182	      size_t n = len - done;
183	      if (n > WIN_DATA_SIZE)
184	        n = WIN_DATA_SIZE;
185	      win_store(0, p + done, n);
186	      intptr_t r = win_syscall(VH_SYS_WRITE, fd, WIN_DATA_VA, n, 0);
187	      if (r < 0)
188	        return done ? (ssize_t) done : (ssize_t) r;
189	      done += (size_t) r;
190	      if ((size_t) r < n)
191	        break; /* short write */
192	    }
193	    return (ssize_t) done;
194	  }
195	  for (size_t i = 0; i < len; ++i)
196	    uart_putc(((const char*) ptr)[i]);
197	  return (ssize_t) len;
198	}
199	
200	__attribute__((used)) ssize_t _read(int fd, void* buf, size_t len)
201	{
202	  if (fd > 2) {
203	    unsigned char* p = (unsigned char*) buf;
204	    size_t done = 0;
205	    while (done < len) {
206	      size_t n = len - done;
207	      if (n > WIN_DATA_SIZE)
208	        n = WIN_DATA_SIZE;
209	      intptr_t r = win_syscall(VH_SYS_READ, fd, WIN_DATA_VA, n, 0);
210	      if (r < 0)
211	        return done ? (ssize_t) done : (ssize_t) r;
212	      if (r > 0)
213	        win_load(p + done, 0, (size_t) r);
214	      done += (size_t) r;
215	      if ((size_t) r < n)
216	        break; /* EOF or short read */
217	    }
218	    return (ssize_t) done;
219	  }
220	  return 0; /* no console input on either engine: EOF */
221	}
222	
223	__attribute__((used)) int _fstat(int fd, struct stat* st)
224	{
225	  if (fd > 2) {
226	    win_store(0, st, sizeof(*st));
227	    intptr_t ret = win_syscall(VH_SYS_FSTAT, fd, WIN_DATA_VA, 0, 0);
228	    if (ret == 0)
229	      win_load(st, 0, sizeof(*st));
230	    return (int) ret;
231	  }
232	  st->st_mode = S_IFCHR; /* char device -> newlib line-buffers stdout */
233	  return 0;
234	}
